import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"表单 / 服务组件","description":"","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/components-form.md","filePath":"features/ui-editor/components-form.md","lastUpdated":1785013113000}'),e={name:"features/ui-editor/components-form.md"};function h(i,t,n,s,l,b){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="表单-服务组件" tabindex="-1">表单 / 服务组件 <a class="header-anchor" href="#表单-服务组件" aria-label="Permalink to &quot;表单 / 服务组件&quot;">​</a></h1><p>本文档面向 <strong>服务表单（errand_service）</strong> 页面的 <strong>16 个表单组件</strong>。此类页面组件库 <strong>仅显示「表单 / 服务」分类</strong>，用于跑腿下单、可配置服务等场景。</p><div class="tip custom-block"><p class="custom-block-title">页面类型</p><p>表单组件 <strong>只能</strong> 添加到 <strong>服务表单</strong> 页。首页、圈子页等内容组件在此类页面不可用。详见 <a href="/features/ui-editor/page-types#服务表单-errand_service">页面类型 — 服务表单</a>。</p></div><hr><h2 id="计价角色-pricingrole-说明" tabindex="-1">计价角色（pricingRole）说明 <a class="header-anchor" href="#计价角色-pricingrole-说明" aria-label="Permalink to &quot;计价角色（pricingRole）说明&quot;">​</a></h2><p>多个表单项支持 <strong>计价方式</strong>，与页面级 <strong>服务表单配置</strong>（基础价、计价公式）配合使用：</p><table tabindex="0"><thead><tr><th>计价方式</th><th>含义</th><th>适用组件</th></tr></thead><tbody><tr><td><strong>不计价</strong></td><td>不参与费用计算</td><td>多数组件默认</td></tr><tr><td><strong>按数量乘单价</strong></td><td>数值 × 单价（如件数、滑动条数值、图片张数）</td><td>数字步进、滑动条、图片上传、文件上传</td></tr><tr><td><strong>选项 / 开关 / 填写 / 定位差价</strong></td><td>选中项或状态对应的固定加价</td><td>选项、开关、地址、定位选择器</td></tr><tr><td><strong>仅作变量</strong></td><td>不直接加价，但可写入页面计价公式作为变量</td><td>选项、地址、定位选择器等</td></tr></tbody></table><hr><h2 id="服务表单页配置流程" tabindex="-1">服务表单页配置流程 <a class="header-anchor" href="#服务表单页配置流程" aria-label="Permalink to &quot;服务表单页配置流程&quot;">​</a></h2><p>推荐按以下顺序搭建服务表单页：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 表单说明 / 分割线        → 告知用户填写须知、划分区块</span></span>
<span class="line"><span>② 表单项（输入、选项、地址等） → 收集业务字段，按需开启计价</span></span>
<span class="line"><span>③ 费用展示                → 实时展示价格明细与优惠券</span></span>
<span class="line"><span>④ 提交底栏（唯一）          → 吸底合计 + 提交按钮</span></span></code></pre></div><p><strong>补充说明：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>要点</th></tr></thead><tbody><tr><td><strong>说明与分组</strong></td><td>用 <strong>表单说明</strong> 写须知；用 <strong>分割线</strong> 划分「取件信息」「增值服务」等区块</td></tr><tr><td><strong>表单项</strong></td><td>每个需提交数据的组件须设 <strong>唯一 fieldKey</strong>；取件/送达地址请设正确 <strong>地址用途</strong></td></tr><tr><td><strong>费用展示</strong></td><td>建议放在表单项之后；可开启明细行与优惠券对接</td></tr><tr><td><strong>提交底栏</strong></td><td><strong>每页仅一个</strong>，固定吸底；也可额外使用 <strong>提交按钮</strong> 作为页内提交入口（非吸底）</td></tr><tr><td><strong>页面级配置</strong></td><td>点击画布空白处，右侧 <strong>服务表单</strong> Tab 配置履约方式、基础价、计价方式</td></tr></tbody></table><p>保存后须在页面列表 <strong>启用</strong>，并对目标 <strong>区域</strong> 生效。</p><hr><h2 id="页面级-errandmeta-履约与计价" tabindex="-1">页面级 errandMeta（履约与计价） <a class="header-anchor" href="#页面级-errandmeta-履约与计价" aria-label="Permalink to &quot;页面级 errandMeta（履约与计价）&quot;">​</a></h2><p>服务表单页除画布组件外，还有 <strong>页面级业务配置</strong>（保存在 <code>errandMeta</code>，与画布同级）。在编辑器右侧 <strong>服务表单</strong> Tab 中编辑：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>服务场景（templateCode）</strong></td><td>自定义编码，同区域不可重复；用于区分不同服务模板</td></tr><tr><td><strong>履约方式</strong></td><td><strong>平台处理</strong> / <strong>骑手配送</strong> / <strong>无需配送</strong></td></tr><tr><td><strong>基础价</strong></td><td>起步价（元），计入订单基础费用</td></tr><tr><td><strong>计价方式</strong></td><td>按模板选择（如基础价 + 组件加价 + 配送费等），无需手写公式</td></tr><tr><td><strong>展示费用明细</strong></td><td>是否在用户端展示分项明细</td></tr><tr><td><strong>下单后支付</strong></td><td><strong>须先支付</strong> 或 <strong>可后付</strong></td></tr></tbody></table><p>取件/送达地址填写后，系统可估算 <strong>配送距离费</strong>；若使用骑手配送，请在计价方式中包含配送费变量。</p><p>更完整的页面类型与互斥规则见 <a href="/features/ui-editor/page-types#服务表单-errand_service">页面类型说明</a>。</p><hr><h2 id="_1-单行输入-xiaoyi-form-input" tabindex="-1">1. 单行输入（xiaoyi-form-input） <a class="header-anchor" href="#_1-单行输入-xiaoyi-form-input" aria-label="Permalink to &quot;1. 单行输入（xiaoyi-form-input）&quot;">​</a></h2><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>单行文本输入框，用于姓名、备注、物品描述等短文本。支持标题上方/左侧同行两种布局，可选左侧图标或图片。</p><h3 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题</td><td>用户看到的字段名</td><td>单行输入</td></tr><tr><td>字段名 fieldKey</td><td>提交时的键名，须唯一</td><td>field_text</td></tr><tr><td>占位提示</td><td>输入框占位文字</td><td>请输入</td></tr><tr><td>是否必填</td><td>必填 / 选填</td><td>必填</td></tr><tr><td>显示标题</td><td>显示 / 隐藏标题</td><td>显示</td></tr><tr><td>标题位置</td><td>左侧上方 / 左侧同行</td><td>左侧上方</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr><tr><td>图标名 / 图片 URL</td><td>选图标或图片时填写</td><td>—</td></tr></tbody></table><h3 id="计价相关" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>默认</th></tr></thead><tbody><tr><td>不计价</td><td>✅ 默认</td></tr></tbody></table><p>可选：<strong>仅作变量</strong>（供页面计价公式引用，不直接加价）。</p><h3 id="内嵌样式分组" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>内容字号/颜色、占位颜色、内容对齐、边框颜色、圆角、背景色</td></tr><tr><td><strong>前导图标</strong></td><td>前导间距、图标大小/颜色（或图片大小/圆角）</td></tr><tr><td><strong>外层样式</strong></td><td>宽高、外边距、内边距、背景等 → <strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名 <strong>不可与其他组件重复</strong>，否则表单值会联动</li><li>横向布局结构：图标 / 标题 / 输入框（图标与标题在输入框容器外侧）</li></ul><hr><h2 id="_2-多行输入-xiaoyi-form-textarea" tabindex="-1">2. 多行输入（xiaoyi-form-textarea） <a class="header-anchor" href="#_2-多行输入-xiaoyi-form-textarea" aria-label="Permalink to &quot;2. 多行输入（xiaoyi-form-textarea）&quot;">​</a></h2><h3 id="说明-1" tabindex="-1">说明 <a class="header-anchor" href="#说明-1" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>多行文本输入，适合详细描述、留言等较长内容。标题显示在输入框上方。</p><h3 id="属性-1" tabindex="-1">属性 <a class="header-anchor" href="#属性-1" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题</td><td>字段名称</td><td>多行输入</td></tr><tr><td>字段名 fieldKey</td><td>须唯一</td><td>field_textarea</td></tr><tr><td>占位提示</td><td>占位文字</td><td>请输入</td></tr><tr><td>是否必填</td><td>必填 / 选填</td><td>选填</td></tr></tbody></table><h3 id="计价相关-1" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-1" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>默认 <strong>不计价</strong>，不参与费用计算。</p><h3 id="内嵌样式分组-1" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-1" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>内容字号/颜色、占位颜色、边框颜色/粗细、圆角、背景色</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-1" tabindex="-1">约束 <a class="header-anchor" href="#约束-1" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>无标题位置、左侧图标等单行输入的高级布局选项</li></ul><hr><h2 id="_3-数字步进-xiaoyi-form-number" tabindex="-1">3. 数字步进（xiaoyi-form-number） <a class="header-anchor" href="#_3-数字步进-xiaoyi-form-number" aria-label="Permalink to &quot;3. 数字步进（xiaoyi-form-number）&quot;">​</a></h2><h3 id="说明-2" tabindex="-1">说明 <a class="header-anchor" href="#说明-2" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>带 <strong>加减步进器</strong> 的数字输入，常用于件数、份数、人数。可配置最小/最大值、步长、单位。</p><h3 id="属性-2" tabindex="-1">属性 <a class="header-anchor" href="#属性-2" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>同通用表单字段</td><td>数量 / package_count / 必填</td></tr><tr><td>显示标题 / 标题位置</td><td>显示标题及位置</td><td>显示 / 左侧同行</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr><tr><td>单位</td><td>如「件」，可留空</td><td>—</td></tr><tr><td>最小值 / 最大值 / 步长</td><td>数值范围与步进</td><td>1 / 99 / 1</td></tr></tbody></table><h3 id="计价相关-2" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-2" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>按数量乘单价</strong>（默认）</td><td>填写 <strong>每件单价</strong>（元）；费用 = 当前数量 × 单价</td></tr><tr><td>不计价 / 开关加价 / 仅作变量</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-2" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-2" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>步进器样式</strong></td><td>按钮边长、按钮间距、内容字号/颜色、单位颜色、按钮圆角、按钮背景色</td></tr><tr><td><strong>前导图标</strong></td><td>同单行输入</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-2" tabindex="-1">约束 <a class="header-anchor" href="#约束-2" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>布局：图标 / 标题 / 步进器，步进按钮在右侧独立显示</li></ul><hr><h2 id="_4-滑动条-xiaoyi-form-slider" tabindex="-1">4. 滑动条（xiaoyi-form-slider） <a class="header-anchor" href="#_4-滑动条-xiaoyi-form-slider" aria-label="Permalink to &quot;4. 滑动条（xiaoyi-form-slider）&quot;">​</a></h2><h3 id="说明-3" tabindex="-1">说明 <a class="header-anchor" href="#说明-3" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>可拖动的 <strong>滑动条</strong> 选值。上行显示标题与当前值，下行为轨道与滑块。适合比例、权重、满意度等场景。</p><h3 id="属性-3" tabindex="-1">属性 <a class="header-anchor" href="#属性-3" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>通用字段</td><td>标题 / field_slider / 选填</td></tr><tr><td>显示标题 / 左侧图标</td><td>标题与图标配置</td><td>显示 / 无</td></tr><tr><td>最小值 / 最大值 / 步长</td><td>取值范围</td><td>0 / 100 / 1</td></tr><tr><td>默认值</td><td>初始滑块位置</td><td>50</td></tr><tr><td>显示当前值 / 显示两端值</td><td>是否展示数值</td><td>显示 / 隐藏</td></tr><tr><td>值前缀 / 值后缀</td><td>如 ¥、%、件</td><td>后缀默认 %</td></tr><tr><td>小数位数</td><td>当前值显示精度</td><td>0</td></tr></tbody></table><h3 id="计价相关-3" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-3" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>不计价</strong>（默认）</td><td>—</td></tr><tr><td><strong>按数量乘单价</strong></td><td>填写 <strong>每单位单价</strong>；费用 = 滑块值 × 单价</td></tr></tbody></table><h3 id="内嵌样式分组-3" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-3" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>内容字号/颜色、边框、圆角、背景（滑动条容器）</td></tr><tr><td><strong>滑动条轨道</strong></td><td>已选/未选轨道色、轨道高度/圆角、点击热区高度</td></tr><tr><td><strong>滑块与数值</strong></td><td>滑块大小/填充色/描边、当前值字号/颜色/字重、两端值字号/颜色</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-3" tabindex="-1">约束 <a class="header-anchor" href="#约束-3" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>标题位置固定为：上行标题 + 当前值，下行滑动条</li></ul><hr><h2 id="_5-选项-xiaoyi-form-options" tabindex="-1">5. 选项（xiaoyi-form-options） <a class="header-anchor" href="#_5-选项-xiaoyi-form-options" aria-label="Permalink to &quot;5. 选项（xiaoyi-form-options）&quot;">​</a></h2><h3 id="说明-4" tabindex="-1">说明 <a class="header-anchor" href="#说明-4" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p><strong>单选或多选</strong> 选项组（旧画布中的「单选」「多选」节点已合并为此组件）。每个选项可设名称与选中加价。</p><h3 id="属性-4" tabindex="-1">属性 <a class="header-anchor" href="#属性-4" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>通用字段</td><td>选项 / field_options / 选填</td></tr><tr><td>选择模式</td><td><strong>单选</strong> 或 <strong>多选</strong></td><td>单选</td></tr><tr><td>最多可选</td><td>多选时：不限 / 最多 N 项</td><td>不限</td></tr><tr><td>排列方式</td><td>横排 / 竖排</td><td>横排</td></tr><tr><td>选项对齐</td><td>左 / 中 / 右</td><td>左</td></tr><tr><td>选项间距</td><td>选项之间的间距</td><td>10rpx</td></tr><tr><td>显示标题 / 标题位置</td><td>选项上方 / 选项左侧</td><td>显示 / 选项上方</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr><tr><td><strong>选项列表</strong></td><td>每项：名称、默认选中、选中加价</td><td>见编辑器</td></tr></tbody></table><h3 id="计价相关-4" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-4" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>选项差价</strong>（默认）</td><td>每项配置 <strong>选中加价</strong>（元）；单选取选中项，<strong>多选累加</strong></td></tr><tr><td>不计价 / 仅作变量</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-4" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-4" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>选项样式</strong></td><td>选项字号、未选/选中文字色、边框色、选中背景色、圆角</td></tr><tr><td><strong>前导图标</strong></td><td>同单行输入</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-4" tabindex="-1">约束 <a class="header-anchor" href="#约束-4" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>单选仅能设 <strong>一个</strong> 默认项；多选可设多个默认项</li><li>多选时各选中项加价 <strong>一起累加</strong></li></ul><hr><h2 id="_6-开关-xiaoyi-form-switch" tabindex="-1">6. 开关（xiaoyi-form-switch） <a class="header-anchor" href="#_6-开关-xiaoyi-form-switch" aria-label="Permalink to &quot;6. 开关（xiaoyi-form-switch）&quot;">​</a></h2><h3 id="说明-5" tabindex="-1">说明 <a class="header-anchor" href="#说明-5" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>布尔开关，布局为：左侧图标/标题 + 右侧开关。适合「需要小票」「加急处理」等是/否选项。</p><h3 id="属性-5" tabindex="-1">属性 <a class="header-anchor" href="#属性-5" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>通用字段</td><td>需要小票 / field_switch / 选填</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr></tbody></table><h3 id="计价相关-5" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-5" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>开关加价</strong>（默认）</td><td><strong>开启时加价</strong>、<strong>关闭时加价</strong>（元），按当前状态取对应金额</td></tr><tr><td>不计价 / 按数量乘单价 / 仅作变量</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-5" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-5" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>前导图标间距与样式</td></tr><tr><td><strong>开关样式</strong></td><td>开启颜色</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-5" tabindex="-1">约束 <a class="header-anchor" href="#约束-5" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li></ul><hr><h2 id="_7-时间选择-xiaoyi-form-datetime" tabindex="-1">7. 时间选择（xiaoyi-form-datetime） <a class="header-anchor" href="#_7-时间选择-xiaoyi-form-datetime" aria-label="Permalink to &quot;7. 时间选择（xiaoyi-form-datetime）&quot;">​</a></h2><h3 id="说明-6" tabindex="-1">说明 <a class="header-anchor" href="#说明-6" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>从管理员预设的 <strong>日期 + 时段</strong> 中选择，用户 <strong>不可自由输入</strong> 时间。支持「文本时间」与「截止时间」两种提交格式。</p><h3 id="属性-6" tabindex="-1">属性 <a class="header-anchor" href="#属性-6" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 占位提示 / 是否必填</td><td>通用字段</td><td>时间选择 / field_datetime / 请选择时间</td></tr><tr><td>显示标题 / 标题位置</td><td>选择框上方 / 选择框左侧</td><td>显示</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr><tr><td>时间类型</td><td><strong>文本时间</strong>（如「明天 10:00-11:00」）或 <strong>截止时间</strong>（时段结束时刻）</td><td>文本时间</td></tr><tr><td>日期选项</td><td>今天、明天、后天等</td><td>可勾选</td></tr><tr><td>上午时段 / 下午时段</td><td>各时段起止时间，可增删</td><td>如 09:00-10:00</td></tr></tbody></table><h3 id="计价相关-6" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-6" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>默认 <strong>不计价</strong>。</p><h3 id="内嵌样式分组-6" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-6" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>内容字号/颜色/对齐、占位颜色、箭头颜色、边框、圆角、背景</td></tr><tr><td><strong>前导图标</strong></td><td>同单行输入</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-6" tabindex="-1">约束 <a class="header-anchor" href="#约束-6" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>用户只能从配置的日期与时段中选择</li></ul><hr><h2 id="_8-图片上传-xiaoyi-form-image" tabindex="-1">8. 图片上传（xiaoyi-form-image） <a class="header-anchor" href="#_8-图片上传-xiaoyi-form-image" aria-label="Permalink to &quot;8. 图片上传（xiaoyi-form-image）&quot;">​</a></h2><h3 id="说明-7" tabindex="-1">说明 <a class="header-anchor" href="#说明-7" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>用户上传图片，以缩略图网格展示。副标题显示在标题同行右侧（如「最多上传 3 张」）。</p><h3 id="属性-7" tabindex="-1">属性 <a class="header-anchor" href="#属性-7" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>通用字段</td><td>上传图片 / field_images / 选填</td></tr><tr><td>显示标题 / 左侧图标</td><td>—</td><td>显示 / 无</td></tr><tr><td>副标题</td><td>标题右侧说明，留空不显示</td><td>最多上传3张照片</td></tr><tr><td>图片对齐</td><td>左 / 中 / 右</td><td>左</td></tr><tr><td>最多张数</td><td>上传上限</td><td>3</td></tr><tr><td>单张上限 (MB)</td><td>单文件大小限制</td><td>5</td></tr></tbody></table><h3 id="计价相关-7" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-7" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>按数量乘单价</strong>（默认）</td><td><strong>每张图片加价</strong>（元）；费用 = 已上传张数 × 单价</td></tr><tr><td>不计价 / 仅作变量</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-7" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-7" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>前导图标样式</td></tr><tr><td><strong>图片样式</strong></td><td>缩略图边长/圆角、添加框边框色、副标题字号/颜色</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-7" tabindex="-1">约束 <a class="header-anchor" href="#约束-7" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li></ul><hr><h2 id="_9-文件上传-xiaoyi-form-file" tabindex="-1">9. 文件上传（xiaoyi-form-file） <a class="header-anchor" href="#_9-文件上传-xiaoyi-form-file" aria-label="Permalink to &quot;9. 文件上传（xiaoyi-form-file）&quot;">​</a></h2><h3 id="说明-8" tabindex="-1">说明 <a class="header-anchor" href="#说明-8" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>上传 PDF、文档、表格等 <strong>非图片文件</strong>。标题旁显示「已选/上限」计数。</p><div class="warning custom-block"><p class="custom-block-title">平台限制</p><p><strong>小程序端暂不支持</strong> 选择文件；主要面向 H5 / App。</p></div><h3 id="属性-8" tabindex="-1">属性 <a class="header-anchor" href="#属性-8" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>通用字段</td><td>文件上传 / field_files / 选填</td></tr><tr><td>显示标题 / 左侧图标</td><td>—</td><td>显示 / 无</td></tr><tr><td>按钮文案</td><td>添加文件按钮文字</td><td>+ 文件</td></tr><tr><td>最多文件数</td><td>上传上限</td><td>3</td></tr><tr><td>单文件上限 (MB)</td><td>单文件大小</td><td>20</td></tr><tr><td>允许格式</td><td>扩展名列表，逗号分隔</td><td>.pdf,.doc,.docx,…</td></tr></tbody></table><h3 id="计价相关-8" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-8" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>按数量乘单价</strong>（默认）</td><td><strong>每个文件加价</strong>（元）</td></tr><tr><td>不计价 / 仅作变量</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-8" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-8" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>前导图标样式</td></tr><tr><td><strong>文件样式</strong></td><td>按钮背景/文字色/字号/圆角；列表项背景/圆角/内边距/间距；文件名字号/颜色；删除图标色/大小</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-8" tabindex="-1">约束 <a class="header-anchor" href="#约束-8" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>小程序端不可用</li></ul><hr><h2 id="_10-分割线-xiaoyi-form-divider" tabindex="-1">10. 分割线（xiaoyi-form-divider） <a class="header-anchor" href="#_10-分割线-xiaoyi-form-divider" aria-label="Permalink to &quot;10. 分割线（xiaoyi-form-divider）&quot;">​</a></h2><h3 id="说明-9" tabindex="-1">说明 <a class="header-anchor" href="#说明-9" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>带可选文案的分割线，用于表单 <strong>分组标题</strong> 或视觉分隔。不参与数据提交与计价。</p><h3 id="属性-9" tabindex="-1">属性 <a class="header-anchor" href="#属性-9" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>文案</td><td>分组标题，可留空</td><td>分组标题</td></tr><tr><td>线条类型</td><td>实线 / 虚线 / 点线 / 双线 / 无线条</td><td>实线</td></tr><tr><td>布局</td><td>居中夹标题 / 标题左对齐</td><td>居中夹标题</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr></tbody></table><h3 id="计价相关-9" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-9" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>无。不参与计价。</p><h3 id="内嵌样式分组-9" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-9" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>分割线样式</strong></td><td>线条颜色/粗细、文字字号/颜色、前导图标样式</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab（建议外层背景透明）</td></tr></tbody></table><h3 id="约束-9" tabindex="-1">约束 <a class="header-anchor" href="#约束-9" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>无 fieldKey，不收集用户数据</li><li>同一页面可添加多个</li></ul><hr><h2 id="_11-表单说明-xiaoyi-form-notice" tabindex="-1">11. 表单说明（xiaoyi-form-notice） <a class="header-anchor" href="#_11-表单说明-xiaoyi-form-notice" aria-label="Permalink to &quot;11. 表单说明（xiaoyi-form-notice）&quot;">​</a></h2><h3 id="说明-10" tabindex="-1">说明 <a class="header-anchor" href="#说明-10" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>表单内 <strong>提示条</strong>，用于填写须知、警告或注意事项。支持信息 / 警告 / 危险三种类型配色。</p><h3 id="属性-10" tabindex="-1">属性 <a class="header-anchor" href="#属性-10" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>内容</td><td>说明正文</td><td>请如实填写信息…</td></tr><tr><td>类型</td><td>信息 / 警告 / 危险</td><td>信息</td></tr><tr><td>显示图标</td><td>是否显示左侧类型图标</td><td>显示</td></tr><tr><td>左侧图标</td><td>默认（随类型）/ 字体图标 / 图片</td><td>默认</td></tr><tr><td>内容对齐</td><td>左 / 中 / 右</td><td>左</td></tr></tbody></table><h3 id="计价相关-10" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-10" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>无。</p><h3 id="内嵌样式分组-10" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-10" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>说明样式</strong></td><td>字号、提示条文案色/背景色（留空跟随类型）、前导图标样式</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab；外层容器背景建议透明，避免与提示条背景叠色</td></tr></tbody></table><h3 id="约束-10" tabindex="-1">约束 <a class="header-anchor" href="#约束-10" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>无 fieldKey</li><li>选「默认」图标且开启显示图标时，按类型自动使用对应图标</li></ul><hr><h2 id="_12-地址-xiaoyi-form-address" tabindex="-1">12. 地址（xiaoyi-form-address） <a class="header-anchor" href="#_12-地址-xiaoyi-form-address" aria-label="Permalink to &quot;12. 地址（xiaoyi-form-address）&quot;">​</a></h2><h3 id="说明-11" tabindex="-1">说明 <a class="header-anchor" href="#说明-11" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>点击跳转 <strong>地址填写页</strong>，用于取件、送达或普通地址。编辑器内可切换「未填写 / 已填写」预览排版。</p><h3 id="属性-11" tabindex="-1">属性 <a class="header-anchor" href="#属性-11" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 占位提示 / 是否必填</td><td>通用字段</td><td>地址 / pickup_addr / 点击填写地址 / 必填</td></tr><tr><td>地址用途</td><td><strong>取件</strong> / <strong>送达</strong> / <strong>普通地址</strong></td><td>取件</td></tr><tr><td>显示标题 / 标题位置</td><td>输入框上方 / 输入框左侧</td><td>显示</td></tr><tr><td>左侧图标</td><td>无 / 字体图标 / 图片</td><td>无</td></tr><tr><td>预览展示</td><td>编辑器内：未填写 / 已填写</td><td>已填写</td></tr></tbody></table><h3 id="计价相关-11" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-11" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>不计价</strong>（默认）</td><td>—</td></tr><tr><td><strong>填写加价</strong></td><td>用户填写地址后固定加价（元）</td></tr><tr><td><strong>仅作变量</strong></td><td>供公式引用</td></tr></tbody></table><p>取件、送达地址填写后，系统可 <strong>自动估算配送距离费</strong>；使用骑手配送时请在页面计价方式中加入 <strong>配送费</strong>。</p><h3 id="内嵌样式分组-11" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-11" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>输入区样式</strong></td><td>内容字号/颜色/对齐、占位颜色、箭头颜色、边框、圆角、背景</td></tr><tr><td><strong>前导图标</strong></td><td>同单行输入</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-11" tabindex="-1">约束 <a class="header-anchor" href="#约束-11" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>编辑器内无法真实选地址，仅预览排版</li><li>取件 + 送达地址配合骑手履约使用</li></ul><hr><h2 id="_13-定位选择器-xiaoyi-form-location-picker" tabindex="-1">13. 定位选择器（xiaoyi-form-location-picker） <a class="header-anchor" href="#_13-定位选择器-xiaoyi-form-location-picker" aria-label="Permalink to &quot;13. 定位选择器（xiaoyi-form-location-picker）&quot;">​</a></h2><h3 id="说明-12" tabindex="-1">说明 <a class="header-anchor" href="#说明-12" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>从管理员预设的 <strong>地点列表</strong> 中单选。每项含名称、区县、地址、经纬度、联系人等；可通过地图搜索填入。</p><h3 id="属性-12" tabindex="-1">属性 <a class="header-anchor" href="#属性-12" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题 / fieldKey / 是否必填</td><td>通用字段</td><td>选择定位 / location_pick / 选填</td></tr><tr><td>显示标题 / 显示箭头</td><td>—</td><td>显示 / 显示</td></tr><tr><td><strong>定位列表</strong></td><td>每项：图片、名称、区县、详细/完整地址、经纬度、联系人、手机号、选中加价</td><td>可增删</td></tr></tbody></table><h3 id="计价相关-12" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-12" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>计价方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>定位差价</strong>（默认）</td><td>每个定位单独配置 <strong>选中加价</strong>（元）</td></tr><tr><td>不计价 / 仅作变量</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-12" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-12" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题样式</strong></td><td>字号、颜色、字重</td></tr><tr><td><strong>定位卡片样式</strong></td><td>卡片间距/内边距/圆角、默认/选中背景、图片边长/圆角、标题/副标题字号颜色、箭头颜色</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-12" tabindex="-1">约束 <a class="header-anchor" href="#约束-12" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>字段名须唯一</li><li>须为每个定位填写有效经纬度（可用「搜索地址并填入」）</li></ul><hr><h2 id="_14-费用展示-xiaoyi-form-price-display" tabindex="-1">14. 费用展示（xiaoyi-form-price-display） <a class="header-anchor" href="#_14-费用展示-xiaoyi-form-price-display" aria-label="Permalink to &quot;14. 费用展示（xiaoyi-form-price-display）&quot;">​</a></h2><h3 id="说明-13" tabindex="-1">说明 <a class="header-anchor" href="#说明-13" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>在表单中 <strong>实时展示价格</strong>，随用户填写内容更新。可展示分项明细、总计、优惠券抵扣。</p><h3 id="属性-13" tabindex="-1">属性 <a class="header-anchor" href="#属性-13" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>标题文案</td><td>区块标题</td><td>价格明细</td></tr><tr><td>说明文案</td><td>标题旁辅助说明</td><td>费用将随填写内容实时更新</td></tr><tr><td>计价公式</td><td>可选自定义表达式；留空则用页面级计价</td><td>—</td></tr><tr><td>展示明细</td><td>展示 / 不展示分项</td><td>展示</td></tr><tr><td>右侧辅助文案</td><td>标题行右侧提示</td><td>显示</td></tr><tr><td>对接优惠券</td><td>开启后试算最优券、支持用户换券</td><td>开启</td></tr><tr><td><strong>明细标签</strong>（展示明细时）</td><td>基础费、加价、配送、优惠券、总计、应付及辅助文案</td><td>可自定义</td></tr></tbody></table><h3 id="计价相关-13" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-13" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>本组件 <strong>展示</strong> 计价结果，本身不参与 field 级 pricingRole。价格由页面 <strong>errandMeta</strong> 与各表单项加价共同计算。</p><h3 id="内嵌样式分组-13" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-13" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>标题与说明</strong></td><td>标题字号/颜色/字重、说明字号/颜色</td></tr><tr><td><strong>明细行样式</strong></td><td>标签/辅助文/行金额字号颜色、行间距</td></tr><tr><td><strong>总计样式</strong></td><td>总计标签/金额字号颜色、分隔线、简模式金额字号</td></tr><tr><td><strong>内嵌面板</strong></td><td>面板背景/圆角/内边距（留空则铺在卡片上）</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab 控制外层卡片</td></tr></tbody></table><h3 id="约束-13" tabindex="-1">约束 <a class="header-anchor" href="#约束-13" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>建议放在表单项之后、提交底栏之前</li><li>关闭「展示明细」时仅显示合计与辅助文案</li></ul><hr><h2 id="_15-提交底栏-xiaoyi-form-bottom-bar" tabindex="-1">15. 提交底栏（xiaoyi-form-bottom-bar） <a class="header-anchor" href="#_15-提交底栏-xiaoyi-form-bottom-bar" aria-label="Permalink to &quot;15. 提交底栏（xiaoyi-form-bottom-bar）&quot;">​</a></h2><h3 id="说明-14" tabindex="-1">说明 <a class="header-anchor" href="#说明-14" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p><strong>固定吸底</strong> 的提交栏：左侧 <strong>实时合计</strong>，右侧 <strong>提交按钮</strong>。是服务表单页的标准提交入口。</p><div class="warning custom-block"><p class="custom-block-title">唯一性</p><p><strong>每页仅可添加一个</strong> 提交底栏。重复添加时编辑器会提示或置灰。</p></div><h3 id="属性-14" tabindex="-1">属性 <a class="header-anchor" href="#属性-14" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>价格标签</td><td>左侧金额前的文字</td><td>合计</td></tr><tr><td>按钮文案</td><td>提交按钮文字</td><td>立即提交</td></tr><tr><td>按钮图标 / 大小 / 颜色</td><td>可选购物车等图标</td><td>shopping-cart-o</td></tr><tr><td>确认弹窗</td><td>提交前是否二次确认</td><td>开启</td></tr><tr><td>确认标题 / 确认说明</td><td>弹窗文案</td><td>确认提交 / 确认提交当前表单？</td></tr></tbody></table><h3 id="计价相关-14" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-14" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>左侧合计金额 <strong>自动联动</strong> 页面计价结果，无需单独配置 pricingRole。</p><h3 id="内嵌样式分组-14" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-14" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>价格样式</strong></td><td>标签字号/颜色、金额字号/单位字号/颜色</td></tr><tr><td><strong>按钮与底栏</strong></td><td>按钮背景/文字色/字号/高度/圆角/最小宽度、底栏背景、顶部分割线色</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab（底栏内边距等）</td></tr></tbody></table><h3 id="约束-14" tabindex="-1">约束 <a class="header-anchor" href="#约束-14" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li><strong>每页唯一</strong>，固定吸底</li><li>与 <strong>提交按钮</strong> 二选一或并存：底栏吸底，提交按钮在页内滚动区域</li></ul><hr><h2 id="_16-提交按钮-xiaoyi-form-submit" tabindex="-1">16. 提交按钮（xiaoyi-form-submit） <a class="header-anchor" href="#_16-提交按钮-xiaoyi-form-submit" aria-label="Permalink to &quot;16. 提交按钮（xiaoyi-form-submit）&quot;">​</a></h2><h3 id="说明-15" tabindex="-1">说明 <a class="header-anchor" href="#说明-15" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>页内 <strong>大按钮</strong> 提交入口（非吸底）。可配主文案、副文案、顶部须知、图标与确认弹窗。布局参考结算页：顶部灰色须知 + 胶囊主按钮。</p><h3 id="属性-15" tabindex="-1">属性 <a class="header-anchor" href="#属性-15" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td>按钮文案</td><td>主按钮文字</td><td>立即提交</td></tr><tr><td>副文案</td><td>按钮内第二行，可选</td><td>—</td></tr><tr><td>顶部说明</td><td>按钮上方须知</td><td>提交即表示您已阅读并同意…</td></tr><tr><td>按钮图标 / 位置 / 大小</td><td>可选，左或右</td><td>—</td></tr><tr><td>确认弹窗 / 确认标题 / 确认说明</td><td>同提交底栏</td><td>开启</td></tr></tbody></table><h3 id="计价相关-15" tabindex="-1">计价相关 <a class="header-anchor" href="#计价相关-15" aria-label="Permalink to &quot;计价相关&quot;">​</a></h3><p>无 field 级计价。点击后按页面计价结果创建订单。</p><h3 id="内嵌样式分组-15" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-15" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分组</th><th>主要字段</th></tr></thead><tbody><tr><td><strong>按钮外观</strong></td><td>背景色、文字色、字号、字重、高度、圆角、边框</td></tr><tr><td><strong>副文案与说明</strong></td><td>副文/说明字号颜色、说明对齐</td></tr><tr><td><strong>外层样式</strong></td><td><strong>「样式」</strong> Tab</td></tr></tbody></table><h3 id="约束-15" tabindex="-1">约束 <a class="header-anchor" href="#约束-15" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>同一页面 <strong>可多个</strong>（ unlike 提交底栏）</li><li>通常与 <strong>提交底栏</strong> 择一为主；若两者并存，请避免重复提交逻辑混淆</li></ul><hr><h2 id="通用约束汇总" tabindex="-1">通用约束汇总 <a class="header-anchor" href="#通用约束汇总" aria-label="Permalink to &quot;通用约束汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><strong>页面类型</strong></td><td>16 个组件 <strong>仅 errand_service 页</strong> 可添加</td></tr><tr><td><strong>提交底栏唯一</strong></td><td>每页 <strong>最多 1 个</strong></td></tr><tr><td><strong>fieldKey 唯一</strong></td><td>重复时编辑器警告，并提供「一键修复重复字段名」</td></tr><tr><td><strong>样式双层</strong></td><td>属性 Tab 内嵌样式 + 顶部 <strong>「样式」</strong> Tab 外层容器</td></tr><tr><td><strong>保存与启用</strong></td><td>编辑后须 <strong>保存</strong> 并在列表 <strong>启用</strong> 才对用户生效</td></tr></tbody></table><hr><h2 id="系列导航" tabindex="-1">系列导航 <a class="header-anchor" href="#系列导航" aria-label="Permalink to &quot;系列导航&quot;">​</a></h2><ul><li>上一篇：<a href="/features/ui-editor/components-marketing">运营模块组件</a></li><li>下一篇：<a href="/features/ui-editor/tabbar">TabBar 配置</a></li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ui-editor/page-types#服务表单-errand_service">页面类型 — 服务表单</a></li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li><li><a href="/features/errand">跑腿业务</a></li><li><a href="/features/ui-editor/">UI 编辑器概览</a></li></ul>`,224)])])}const u=d(e,[["render",h]]);export{c as __pageData,u as default};
